<template>
  <el-tag :type="tagType" size="small">
    {{ displayText }}
  </el-tag>
</template>

<script setup lang="ts">
import { computed } from 'vue'

const props = defineProps<{
  status: string
  type?: 'node' | 'severity' | 'incident' | 'task' | 'default'
}>()

const displayText = computed(() => props.status || '-')

const tagType = computed(() => {
  const s = props.status?.toLowerCase() || ''
  const map: Record<string, string> = {
    node_online: 'success',
    node_offline: 'danger',
    node_unknown: 'info',
    severity_critical: 'danger',
    severity_warning: 'warning',
    severity_info: 'info',
    incident_open: 'danger',
    incident_acknowledged: 'warning',
    incident_resolved: 'success',
    incident_closed: 'info',
    task_pending: 'warning',
    task_running: 'primary',
    task_success: 'success',
    task_failed: 'danger',
    task_timeout: 'danger',
    task_cancelled: 'info',
  }

  const key = `${props.type || 'default'}_${s}`
  if (map[key]) return map[key]

  // 通用回退
  if (s === 'success' || s === 'online' || s === 'resolved') return 'success'
  if (s === 'failed' || s === 'offline' || s === 'error' || s === 'critical' || s === 'open') return 'danger'
  if (s === 'warning' || s === 'pending' || s === 'acknowledged') return 'warning'
  if (s === 'info' || s === 'closed' || s === 'cancelled') return 'info'
  return 'info'
})
</script>
